INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (50, 21, 'Ice Cream', 'ice-cream', NULL, NULL, NULL, 1, 1, 2, NULL, NULL, NULL, NULL, 0, '2026-09-18 05:14:54', '2026-09-18 05:14:54', 'grocery', NULL);
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (51, NULL, 'Rice & Grains', 'rice-grains', 'Aged basmati, red rice, millets', 'Aged basmati, red rice, millets', 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Our rice and grains come from single-origin cooperative farms — aged basmati from Punjab, red matta rice from Kerala and foxtail, little and barnyard millets from Karnataka. Every lot is sun-dried, cleaned by hand and milled close to dispatch so it reaches you fresh.</p><h3>How to choose</h3><p>Pick aged basmati for biryani and pulao, sona masoori for everyday meals, and millets for a fibre-rich, low-GI alternative to polished rice.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (52, NULL, 'Pulses & Dals', 'pulses-dals', 'Unpolished, protein-rich', 'Unpolished, protein-rich', 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Unpolished dals keep their natural bran and protein. Ours are cleaned without oil or water polish, so they cook faster and taste of the field, not the factory.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (53, NULL, 'Flour & Atta', 'flour-atta', 'Stone-ground, fresh every week', 'Stone-ground, fresh every week', 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 2, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Stone-grinding keeps the wheat germ and bran in the flour. We mill in small batches every week — the date is printed on every pack.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (54, NULL, 'Spices & Masalas', 'spices-masalas', 'Sun-dried and freshly ground', 'Sun-dried and freshly ground', 'https://images.unsplash.com/photo-1532336414038-cf19250c5757?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 3, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Whole spices from Kerala, Andhra and Rajasthan, ground in small batches for maximum aroma. No fillers, no colours.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (55, NULL, 'Oils & Ghee', 'oils-ghee', 'Cold-pressed oils, bilona ghee', 'Cold-pressed oils, bilona ghee', 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 4, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Wood-pressed (kachi ghani) oils retain their natural aroma and nutrients. Our ghee is churned from curd the traditional bilona way.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (56, NULL, 'Sweeteners & Honey', 'sweeteners', 'Jaggery, raw honey, khandsari', 'Jaggery, raw honey, khandsari', 'https://images.unsplash.com/photo-1471943311424-646960669fbc?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 6, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Unrefined sweeteners with their minerals intact — organic jaggery, raw forest honey and khandsari sugar.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (57, NULL, 'Tea & Beverages', 'tea-beverages', 'Estate teas and traditional blends', 'Estate teas and traditional blends', 'https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 7, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Assam and Darjeeling estate teas, masala chai blends and herbal infusions.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (58, NULL, 'Health & Wellness', 'health-wellness', 'Ayurvedic staples and superfoods', 'Ayurvedic staples and superfoods', 'https://images.unsplash.com/photo-1615485500704-8e990f9900f7?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 8, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Turmeric, moringa, ashwagandha and other traditional wellness foods, tested for purity.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (59, NULL, 'Organic Foods', 'organic-foods', 'Certified organic, farm to pack', 'Certified organic, farm to pack', 'https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 9, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Everything in this section is India Organic and NPOP certified — grown without synthetic fertilisers or pesticides.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (60, NULL, 'Snacks', 'snacks', 'Roasted, baked, honest', 'Roasted, baked, honest', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 10, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Roasted makhana, baked chips, trail mixes and traditional namkeen — no palm oil, no MSG.</p>');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `image`, `is_active`, `show_in_menu`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`, `content`) VALUES (61, NULL, 'Gift Boxes', 'gift-boxes', 'Festive hampers', 'Festive hampers', 'https://images.unsplash.com/photo-1512909006721-3d6018887383?w=900&q=80&auto=format&fit=crop&h=900', 1, 1, 11, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:42', '2026-09-18 06:49:42', 'heritage', '<p>Curated hampers of dry fruits, spices, ghee and teas in reusable boxes — for Diwali, weddings and housewarmings.</p>');
