INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (3, 'The Signature Collection', 'the-signature-collection', 'Campaign', 'Behind the lens of our Autumn campaign — shot over three days in a converted textile mill.', '<p>Behind the lens of our Autumn campaign — shot over three days in a converted textile mill.</p><p>Full story coming soon.</p>', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=1200&q=80&auto=format&fit=crop&h=1500', '8 min read', '2026-08-12 10:00:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 04:51:11', 'fashion');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (4, '15-minute paneer bhurji', '15-minute-paneer-bhurji', 'Recipes', 'A weeknight classic: crumbled paneer, onions, tomatoes and a handful of masalas. Ready before the rotis are.', '<h2>Ingredients</h2><ul><li>200 g paneer, crumbled</li><li>1 onion, 2 tomatoes, finely chopped</li><li>1 green chilli, ½ tsp turmeric, 1 tsp garam masala</li><li>Coriander, salt, 1 tbsp oil</li></ul><h2>Method</h2><ol><li>Heat oil, soften the onion and chilli.</li><li>Add tomatoes and spices; cook until the oil separates.</li><li>Fold in the paneer, cook 3 minutes, finish with coriander.</li></ol>', 'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=1400&q=80&auto=format&fit=crop&h=900', '3', '2026-09-17 06:31:49', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (5, 'How to keep fruits and vegetables fresh for longer', 'how-to-store-fruits-and-vegetables', 'Tips', 'Which ones go in the fridge, which stay out, and why bananas should live alone.', '<p>Leafy greens: wash, dry, wrap in a kitchen towel and refrigerate. Tomatoes and bananas: room temperature, away from other fruit — they release ethylene that ripens everything nearby. Potatoes and onions: cool, dark and separate. Berries: unwashed in the fridge; rinse just before eating.</p>', 'https://images.unsplash.com/photo-1610348725531-843dff563e2c?w=1400&q=80&auto=format&fit=crop&h=900', '4', '2026-09-08 06:31:49', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (6, 'A week of meals under ₹999', 'weekly-meal-prep-under-999', 'Budget', 'Dal, rice, two sabzis, eggs and fruit — a realistic plan for two people, with the shopping list.', '<h2>The list</h2><ul><li>Toor dal 1 kg, basmati rice 2 kg, atta 2 kg</li><li>Onions, tomatoes, potatoes, spinach, carrots</li><li>12 eggs, 1 L milk, 200 g paneer</li><li>Bananas and apples for breakfast</li></ul><p>Cook dal and rice in bulk on Sunday; rotate sabzis through the week; keep eggs for quick dinners.</p>', 'https://images.unsplash.com/photo-1547592180-85f173990554?w=1400&q=80&auto=format&fit=crop&h=900', '5', '2026-09-17 06:31:49', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (7, 'How to cook perfect basmati, every time', 'perfect-basmati-every-time', 'Kitchen notes', 'Rinse, soak, ratio, rest — the four steps that turn aged basmati into long, separate, fragrant grains.', '<h2>1. Rinse</h2><p>Wash the rice in cold water until it runs clear — this removes surface starch that makes grains stick.</p><h2>2. Soak</h2><p>Twenty minutes in cold water lets the grains hydrate evenly and lengthen fully.</p><h2>3. Ratio</h2><p>1 cup rice to 1.5 cups water for the absorption method; a pinch of salt and a teaspoon of ghee.</p><h2>4. Rest</h2><p>Once the water is absorbed, take it off the heat and leave it covered for 10 minutes. Fluff with a fork, never a spoon.</p>', 'https://images.unsplash.com/photo-1536304993881-ff6e9eefa2a6?w=1400&q=80&auto=format&fit=crop&h=900', '4', '2026-08-20 07:53:07', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (8, 'Why bilona ghee tastes different', 'why-bilona-ghee-is-different', 'Stories', 'Thirty litres of milk, a day of culturing, and a wooden churn: the slow method behind our A2 ghee.', '<p>Most commercial ghee is made by boiling cream. Bilona ghee starts with milk that is cultured into curd overnight, churned with a wooden bilona to separate the butter, and only then slowly simmered. It takes 30 litres of A2 milk to make one kilo — which is why it is granular, nutty and fragrant in a way boiled-cream ghee never is.</p>', 'https://images.unsplash.com/photo-1589985270826-4b7bb135bc9d?w=1400&q=80&auto=format&fit=crop&h=900', '5', '2026-09-16 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (9, 'Building the everyday masala dabba', 'the-everyday-masala-dabba', 'Kitchen notes', 'Seven spices that cook ninety percent of Indian home food — and how to keep them fresh.', '<p>Turmeric, red chilli, coriander, cumin, mustard seeds, garam masala and asafoetida. Buy whole where you can, grind in small batches, and keep the dabba away from the stove — heat and light are the enemies of aroma.</p>', 'https://images.unsplash.com/photo-1506368249639-73a05d6f6488?w=1400&q=80&auto=format&fit=crop&h=900', '3', '2026-09-12 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (10, 'Millets, back on the Indian plate', 'millets-back-on-the-plate', 'Wellness', 'Foxtail, little, barnyard, ragi — how to swap one meal a day to millets without anyone at the table noticing.', '<p>Millets were the everyday grain of most of India until polished rice and wheat took over. They are low-GI, high in fibre and grow on rain alone. Start with ragi dosa or foxtail upma — both taste familiar — and move to millet khichdi and pulao once the family is used to the nutty flavour.</p>', 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=1400&q=80&auto=format&fit=crop&h=900', '4', '2026-08-25 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (11, 'Why raw honey crystallises (and why that is good)', 'raw-honey-crystallises', 'Stories', 'Crystallised honey is not spoilt honey. It is the surest sign that nothing was heated, filtered or added.', '<p>Raw honey is a supersaturated sugar solution with pollen and wax particles in it. In winter the glucose settles around those particles and the jar turns creamy and opaque. Stand the jar in warm water for ten minutes to loosen it — never microwave it, which destroys the enzymes you paid for.</p>', 'https://images.unsplash.com/photo-1471943311424-646960669fbc?w=1400&q=80&auto=format&fit=crop&h=900', '3', '2026-08-28 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (12, 'PVC vs CPVC vs UPVC: which pipe for which job?', 'pvc-vs-cpvc-vs-upvc', 'Guides', 'The three most common plastic pipes in Indian homes, and exactly where each one belongs.', '<p><strong>CPVC</strong> handles hot water up to 93 °C, so it goes in bathroom and kitchen hot & cold lines and geyser connections. <strong>UPVC</strong> is for cold water supply — tank lines, garden taps, utility areas. <strong>PVC</strong> is the workhorse for drainage, soil and waste stacks, rainwater and agriculture.</p><p>Never mix cements: CPVC cement for CPVC, UPVC cement for UPVC. A quarter-turn on insertion and 24 hours before pressure testing is the rule for all three.</p>', 'https://images.unsplash.com/photo-1718347791747-35fac02b585e?w=1600&q=80&auto=format&fit=crop&h=900', NULL, '2026-09-09 08:52:13', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 08:33:59', '2026-09-21 08:52:13', 'plumbing');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (13, 'How to choose a water pump for your home', 'choose-a-water-pump', 'Guides', 'Self-priming, submersible or booster? Head, suction and discharge explained in plain language.', '<p>Start with the job: filling an overhead tank from a sump needs a <strong>self-priming monoblock</strong>; pulling from a borewell needs a <strong>submersible</strong>; weak showers on the top floor need a <strong>pressure booster</strong>. Then match the total head (vertical lift plus friction) and the discharge you need in litres per hour.</p>', 'https://images.unsplash.com/photo-1534641614095-6222aed9bdd6?w=1600&q=80&auto=format&fit=crop&h=900', NULL, '2026-09-13 08:52:13', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 08:33:59', '2026-09-21 08:52:13', 'plumbing');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (14, 'Bathroom renovation checklist: every fitting you will need', 'bathroom-renovation-checklist', 'Checklists', 'From concealed bodies to the last angle cock — the complete buying list for a bathroom, in installation order.', '<p>Rough-in first: CPVC lines, concealed mixer bodies, floor traps and the WC outlet. Then sanitaryware — basin and WC. Finally the exposed fittings: mixer, overhead shower, health faucet, angle cocks, flexible hoses and accessories. Our Bathroom starter kit collection bundles the essentials.</p>', 'https://images.unsplash.com/photo-1584622650111-993a426fbf0a?w=1600&q=80&auto=format&fit=crop&h=900', NULL, '2026-09-17 08:52:13', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 08:33:59', '2026-09-21 08:52:13', 'plumbing');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (15, 'How to identify a water leak at home', 'how-to-identify-a-water-leak', 'Leaks', 'Damp patches, a spinning meter and a rising bill — the signs of a hidden leak and how to narrow it down before the plumber arrives.', '<p>Close every tap and check the water meter. If it still moves, water is going somewhere. Then look for damp patches on walls and ceilings, a musty smell in cupboards under sinks, and taps or flushes that never quite stop. Note where the damp is worst — that is usually directly below or beside the leak — and share it with the plumber when you book.</p>', 'https://images.unsplash.com/photo-1542855368-ca6ea825bca2?w=1600&q=80&auto=format&fit=crop&h=900', '4', '2026-09-18 09:49:00', 1, NULL, NULL, NULL, NULL, 0, '2026-09-21 09:49:00', '2026-09-21 09:49:00', 'plumbing-services');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (16, 'What causes low water pressure?', 'what-causes-low-water-pressure', 'Pressure', 'Clogged aerators, half-closed valves, scaled pipes or a tank that is simply too low — the usual suspects and what fixes each.', '<p>If only one tap is weak, unscrew the aerator and rinse it — that fixes most cases. If the whole house is weak, check the main and angle valves are fully open. Old GI pipes scale up inside and choke the flow; the fix is replacement. And if your tank is barely above the top-floor shower, a small booster pump makes a big difference.</p>', 'https://images.unsplash.com/photo-1517646287270-a5a9ca602e5c?w=1600&q=80&auto=format&fit=crop&h=900', '5', '2026-09-12 09:49:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 09:49:00', '2026-09-21 09:49:00', 'plumbing-services');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (17, 'When should you replace a pipe instead of repairing it?', 'when-should-you-replace-a-pipe', 'Pipes', 'Three repairs on the same line in a year, brown water or a GI pipe older than 15 years — replacement is usually cheaper in the long run.', '<p>Repairs make sense for isolated joints and accidental damage. Replacement makes sense when leaks keep coming back along the same run, when water is rusty or discoloured, or when the line is GI and more than 12–15 years old. Modern CPVC and UPVC lines cost less than repeated repairs and civil work.</p>', 'https://images.unsplash.com/photo-1601507622731-4abab94ebeb8?w=1600&q=80&auto=format&fit=crop&h=900', '4', '2026-09-06 09:49:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 09:49:00', '2026-09-21 09:49:00', 'plumbing-services');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (18, 'How to prevent blocked drains', 'how-to-prevent-blocked-drains', 'Drains', 'Grease, hair and wet wipes cause most blockages. A few habits keep your drains running for years.', '<p>Never pour cooking oil or ghee down the sink — wipe pans with paper first. Use a hair catcher in the bathroom drain. Nothing but toilet paper goes in the WC; wipes and sanitary products block sewer lines. Once a month, pour hot water down the kitchen drain to move soft grease along.</p>', 'https://images.unsplash.com/photo-1697652973421-0d688f661d89?w=1600&q=80&auto=format&fit=crop&h=900', '3', '2026-08-31 09:49:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 09:49:00', '2026-09-21 09:49:00', 'plumbing-services');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (19, 'Bathroom plumbing maintenance tips', 'bathroom-plumbing-maintenance-tips', 'Maintenance', 'Ten minutes a month keeps taps, flushes and drains in shape and catches leaks before they reach the flat below.', '<p>Check under the basin for damp, run the flush and listen for it stopping, clean the shower head and tap aerators, and look at the silicone around the basin and WC base. Any drip, gurgle or crack is worth a call before monsoon.</p>', 'https://images.unsplash.com/photo-1629079447777-1e605162dc8d?w=1600&q=80&auto=format&fit=crop&h=900', '4', '2026-08-25 09:49:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 09:49:00', '2026-09-21 09:49:00', 'plumbing-services');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (20, 'Signs you need a professional plumber', 'signs-you-need-a-professional-plumber', 'Guides', 'Some jobs are DIY. These are not — and trying can turn a small problem into a flooded floor.', '<p>Call a professional for concealed leaks, anything involving the main line or the sewer, geyser connections, repeated blockages, and any job that needs breaking tiles or cutting pipes. A washer or aerator is DIY; a joint behind a wall is not.</p>', 'https://images.unsplash.com/photo-1503789146722-cf137a3c0fea?w=1600&q=80&auto=format&fit=crop&h=900', '3', '2026-08-19 09:49:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-21 09:49:00', '2026-09-21 09:49:00', 'plumbing-services');
