INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (1, 'plumbing-services', 'Emergency Plumbing', 'emergency-plumbing', 'alert', 'https://images.unsplash.com/photo-1526898943670-92bfa9f94c12?w=1200&q=80&auto=format&fit=crop&h=800', '24×7 response for burst pipes, major leaks, overflowing drains and no-water situations.', '<p>A plumbing emergency does not wait for office hours. Our emergency team is on call round the clock for burst pipes, major leakages, overflowing drains and sudden loss of water supply. We stop the damage first, then fix the cause properly.</p><p>While the plumber is on the way, our support team stays on the line to help you shut the main valve, isolate the geyser and contain the water.</p>', '["Burst or cracked pipe","Water flooding the floor","Overflowing drain or toilet","Main line leak","No water supply at all"]', '["Priority dispatch, day or night","Temporary fix to stop the damage","Permanent repair with genuine parts","Pressure test before we leave"]', '[{"question":"How fast can you reach?","answer":"In most service areas an emergency plumber is at your door within 60\\u201390 minutes. Call us and we will guide you on the phone meanwhile."},{"question":"Are emergency charges higher?","answer":"Night and holiday visits carry a modest emergency visit charge which we tell you on the call before dispatching."}]', NULL, 1, 1, 1, 0, NULL, '24×7 response for burst pipes, major leaks, overflowing drains and no-water situations.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (2, 'plumbing-services', 'Leak Repair', 'leak-repair', 'droplet', 'https://images.unsplash.com/photo-1676210134188-4c05dd172f89?w=1200&q=80&auto=format&fit=crop&h=800', 'Leak detection and repair for taps, joints, concealed pipes, ceilings and walls.', '<p>Leaks waste water, damage walls and invite seepage in the flat below. Our plumbers locate the source — a worn washer, a failed joint or a cracked concealed pipe — and repair it with genuine parts, testing the line under pressure before leaving.</p>', '["Dripping tap or shower","Damp patch on the wall or ceiling","Water under the sink or basin","Leak from a concealed pipe","Rising water bill with no visible leak"]', '["Leak detection with pressure testing","Joint, washer and seal replacement","Concealed pipe repair with minimal breaking","Wall\\/ceiling patch coordination on request"]', '[{"question":"Can you find a hidden leak without breaking tiles?","answer":"Usually yes \\u2014 we pressure-test each line and use moisture readings to narrow down the spot, so we open only the area that needs repair."}]', NULL, 0, 1, 1, 1, NULL, 'Leak detection and repair for taps, joints, concealed pipes, ceilings and walls.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (3, 'plumbing-services', 'Pipe Repair', 'pipe-repair', 'pipe', 'https://images.unsplash.com/photo-1607472586893-edb57bdc0e39?w=1200&q=80&auto=format&fit=crop&h=800', 'Repair of cracked, corroded, leaking or noisy GI, CPVC, UPVC and PVC pipes.', '<p>Whether it is an old GI line that has rusted through or a CPVC joint that has started to weep, we repair the affected section with the right material and fittings, and secure the run so the problem does not return.</p>', '["Cracked or leaking pipe","Rusted GI pipe","Banging or vibrating pipes","Loose or leaking joint","Frozen or blocked section"]', '["Inspection of the affected run","Section replacement or joint repair","Correct solvent cement and fittings","Clamping and support where needed"]', '[]', NULL, 0, 1, 1, 2, NULL, 'Repair of cracked, corroded, leaking or noisy GI, CPVC, UPVC and PVC pipes.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (4, 'plumbing-services', 'Pipe Replacement', 'pipe-replacement', 'layers', 'https://images.unsplash.com/photo-1545193329-4a052e14eb8f?w=1200&q=80&auto=format&fit=crop&h=800', 'Full or partial replacement of old water-supply and drainage lines with CPVC/UPVC/PVC.', '<p>When repairs stop making sense, we replace the line. We survey the run, give you a written estimate for material and labour, and install a new line with ISI-marked pipes and fittings — tested under pressure and cleaned up before handover.</p>', '["Repeated leaks on an old line","Rusty or discoloured water","Low pressure from clogged GI pipes","Renovation of an old house"]', '["Line survey and material estimate","Removal of old pipes","New CPVC\\/UPVC\\/PVC line with ISI-marked fittings","Pressure testing and clean-up"]', '[{"question":"How long does replacing a bathroom line take?","answer":"A single bathroom is usually done in one working day; a full house takes two to four days depending on the number of lines and civil work."}]', NULL, 0, 0, 1, 3, NULL, 'Full or partial replacement of old water-supply and drainage lines with CPVC/UPVC/PVC.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (5, 'plumbing-services', 'Drain Cleaning', 'drain-cleaning', 'drain', 'https://images.unsplash.com/photo-1745265796934-c34e78554872?w=1200&q=80&auto=format&fit=crop&h=800', 'Machine and manual cleaning of slow or blocked bathroom, kitchen and floor drains.', '<p>Hair, grease, soap and scale build up until the drain stops. We clear the blockage with the right tool — rods, augers or a drain machine — clean the trap and test the flow so the line runs freely again.</p>', '["Slow-draining sink or basin","Water standing in the bathroom","Foul smell from the drain","Gurgling sounds","Repeated blockages"]', '["Drain rodding or machine cleaning","Trap cleaning and refitting","Grease and hair removal","Flow test after cleaning"]', '[]', NULL, 0, 1, 1, 4, NULL, 'Machine and manual cleaning of slow or blocked bathroom, kitchen and floor drains.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (6, 'plumbing-services', 'Blocked Drain Repair', 'blocked-drain-repair', 'drain', 'https://images.unsplash.com/photo-1654440122140-f1fc995ddb34?w=1200&q=80&auto=format&fit=crop&h=800', 'Repair of damaged, collapsed or root-blocked drain lines and traps.', '<p>When cleaning alone does not hold, the pipe itself is the problem. We inspect the line, repair or replace the damaged section and refit traps and gullies so waste flows the way it should.</p>', '["Blockage that keeps coming back","Drain line collapsed or broken","Sewage backing up","Roots in the outdoor line"]', '["Line inspection","Section repair or replacement","Trap and gully replacement","Flow test and clean-up"]', '[]', NULL, 0, 0, 1, 5, NULL, 'Repair of damaged, collapsed or root-blocked drain lines and traps.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (7, 'plumbing-services', 'Bathroom Plumbing', 'bathroom-plumbing', 'bath', 'https://images.unsplash.com/photo-1584622650111-993a426fbf0a?w=1200&q=80&auto=format&fit=crop&h=800', 'Complete bathroom plumbing — new fittings, repairs, leak-proofing and renovations.', '<p>From a dripping mixer to a full renovation, our bathroom plumbers handle supply lines, drainage, fittings and fixtures. We work with your tiler and electrician so the bathroom comes together on schedule.</p>', '["Leaking shower or mixer","Basin or WC leak","Poor drainage on the floor","New bathroom fit-out","Seepage to the flat below"]', '["Concealed and exposed line work","Mixer, shower, basin and WC installation","Floor trap and drainage correction","Waterproofing coordination"]', '[]', NULL, 0, 1, 1, 6, NULL, 'Complete bathroom plumbing — new fittings, repairs, leak-proofing and renovations.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (8, 'plumbing-services', 'Kitchen Plumbing', 'kitchen-plumbing', 'kitchen', 'https://images.unsplash.com/photo-1676210133055-eab6ef033ce3?w=1200&q=80&auto=format&fit=crop&h=800', 'Sink, tap, drain, RO and dishwasher plumbing for modular and traditional kitchens.', '<p>Kitchen plumbing takes daily abuse — grease, hot water and heavy use. We fix leaking traps, blocked drains and weak flow, and connect purifiers, dishwashers and washing machines properly.</p>', '["Leaking sink trap","Blocked kitchen drain","Low flow at the kitchen tap","RO \\/ water purifier connection","Dishwasher or washing machine inlet"]', '["Sink and tap installation or repair","Bottle trap and drain line work","RO, dishwasher and washing machine connections","Leak-proof sealing"]', '[]', NULL, 0, 1, 1, 7, NULL, 'Sink, tap, drain, RO and dishwasher plumbing for modular and traditional kitchens.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (9, 'plumbing-services', 'Tap & Faucet Repair', 'tap-faucet-repair', 'tap', 'https://images.unsplash.com/photo-1542013936693-884638332954?w=1200&q=80&auto=format&fit=crop&h=800', 'Repair and replacement of dripping, stiff, noisy or broken taps and mixers.', '<p>A dripping tap wastes thousands of litres a year. Our plumbers replace cartridges, washers and spindles or fit a new tap or mixer — and check the angle valves behind it while they are there.</p>', '["Dripping tap","Stiff or loose handle","Low flow from one tap","Broken or corroded spout","Leak at the base"]', '["Cartridge, washer and spindle replacement","Aerator cleaning","Tap or mixer replacement","Angle valve check"]', '[{"question":"Do I need to buy the tap myself?","answer":"You can, or our plumber can bring options from trusted brands. You pay for parts only after approving the price."}]', NULL, 0, 1, 1, 8, NULL, 'Repair and replacement of dripping, stiff, noisy or broken taps and mixers.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (10, 'plumbing-services', 'Toilet Repair', 'toilet-repair', 'toilet', 'https://images.unsplash.com/photo-1589824783837-6169889fa20f?w=1200&q=80&auto=format&fit=crop&h=800', 'Flush tank, seat, leak and blockage repairs for all WC types.', '<p>Running flushes, weak flushes, leaks and blockages — we repair every type of WC, from floor-mounted to concealed cisterns, with genuine spares.</p>', '["Flush not working or running continuously","Water leaking around the base","Blocked WC","Loose seat or broken hinge","Weak flush"]', '["Flush valve, float and fill valve replacement","Blockage removal","Wax ring and base sealing","Seat and cover replacement"]', '[]', NULL, 0, 1, 1, 9, NULL, 'Flush tank, seat, leak and blockage repairs for all WC types.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (11, 'plumbing-services', 'Water Tank Services', 'water-tank-services', 'tank', 'https://images.unsplash.com/photo-1562185412-99dacaad0c9a?w=1200&q=80&auto=format&fit=crop&h=800', 'Overhead and underground tank cleaning, installation, float valve and overflow fixes.', '<p>Clean tanks mean clean water. We drain, scrub, disinfect and refill overhead and underground tanks, replace worn float valves and fix overflow and outlet leaks. New tank installation includes the stand, inlet, outlet and overflow lines.</p>', '["Dirty or smelly tank water","Tank overflowing","Float valve not closing","Leak from the tank outlet","New tank installation"]', '["Tank draining and mechanised cleaning","Float valve and ball cock replacement","Inlet, outlet and overflow pipe work","New tank installation on stand"]', '[{"question":"How often should a tank be cleaned?","answer":"Every six months for an overhead tank and at least once a year for an underground sump."}]', NULL, 0, 1, 1, 10, NULL, 'Overhead and underground tank cleaning, installation, float valve and overflow fixes.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (12, 'plumbing-services', 'Water Pump Services', 'water-pump-services', 'pump', 'https://images.unsplash.com/photo-1534641614095-6222aed9bdd6?w=1200&q=80&auto=format&fit=crop&h=800', 'Installation, repair and replacement of monoblock, submersible and booster pumps.', '<p>No water in the tank usually means a pump or suction problem. We diagnose the pump, foot valve and line, repair or replace what is needed, and can add an automatic controller so the tank fills on its own.</p>', '["Pump not lifting water","Pump running but low flow","Noisy or tripping pump","Automatic controller not working","New pump installation"]', '["Pump inspection and priming","Foot valve and suction line check","Pump repair or replacement","Auto-controller and float switch installation"]', '[]', NULL, 0, 0, 1, 11, NULL, 'Installation, repair and replacement of monoblock, submersible and booster pumps.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (13, 'plumbing-services', 'Geyser & Water Heater Plumbing', 'geyser-water-heater-plumbing', 'flame', 'https://images.unsplash.com/photo-1676210134190-3f2c0d5cf58d?w=1200&q=80&auto=format&fit=crop&h=800', 'Geyser installation, inlet/outlet connections, pressure valve and leak repair.', '<p>We install and connect geysers of every brand with the right safety valve and CPVC hot-water lines, and repair leaks and pressure-valve problems on existing units. Electrical connections are handled by a licensed electrician on request.</p>', '["Geyser leaking","No hot water at the tap","Pressure release valve dripping","New geyser installation","Hot water line for a new bathroom"]', '["Geyser mounting and connection","Inlet, outlet and safety valve fitting","CPVC hot-water line work","Leak repair and testing"]', '[]', NULL, 0, 0, 1, 12, NULL, 'Geyser installation, inlet/outlet connections, pressure valve and leak repair.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (14, 'plumbing-services', 'Sewer Line Services', 'sewer-line-services', 'layers', 'https://images.unsplash.com/photo-1697497709686-c433fce09de4?w=1200&q=80&auto=format&fit=crop&h=800', 'Sewer line cleaning, repair and new connections for homes and buildings.', '<p>Sewer problems affect the whole building. We clear and repair sewer lines, clean chambers and manholes, and lay new connections — with proper gradient and inspection chambers.</p>', '["Sewage backing up","Foul smell around the building","Manhole overflowing","Broken sewer pipe","New sewer connection"]', '["Sewer line jetting and rodding","Chamber and manhole cleaning","Pipe repair or replacement","New connection to the municipal line"]', '[]', NULL, 0, 0, 1, 13, NULL, 'Sewer line cleaning, repair and new connections for homes and buildings.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (15, 'plumbing-services', 'Water Pressure Problems', 'water-pressure-problems', 'gauge', 'https://images.unsplash.com/photo-1669920282730-ab422e592f97?w=1200&q=80&auto=format&fit=crop&h=800', 'Diagnosis and fixing of low or uneven water pressure across the house.', '<p>Low pressure has many causes — clogged aerators, half-closed valves, scaled pipes or simply not enough tank height. We check each outlet, clear what is blocked and, if needed, install a pressure booster pump.</p>', '["Weak shower on the top floor","Pressure drops when two taps run","One tap much weaker than others","Air in the line"]', '["Pressure check at every outlet","Aerator, valve and line cleaning","Booster pump recommendation and installation","Tank height and line-size advice"]', '[]', NULL, 0, 1, 1, 14, NULL, 'Diagnosis and fixing of low or uneven water pressure across the house.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (16, 'plumbing-services', 'New Construction Plumbing', 'new-construction-plumbing', 'building', 'https://images.unsplash.com/photo-1747192904662-e03e8da1e0ab?w=1200&q=80&auto=format&fit=crop&h=800', 'Complete plumbing for new homes, floors and buildings — design to handover.', '<p>For new construction we plan the supply and drainage layout, lay concealed lines, install tanks, pumps and sanitaryware, and test everything before handover. We coordinate with your contractor and site engineer throughout.</p>', '["Plumbing for a new house or floor","Concealed line layout","Drainage and sewer design","Tank and pump sizing"]', '["Plumbing layout and material list","Concealed supply and drainage lines","Sanitaryware and fixture installation","Testing and handover documentation"]', '[]', NULL, 0, 0, 1, 15, NULL, 'Complete plumbing for new homes, floors and buildings — design to handover.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (17, 'plumbing-services', 'Commercial Plumbing', 'commercial-plumbing', 'building', 'https://images.unsplash.com/photo-1639600993675-2281b2c939f0?w=1200&q=80&auto=format&fit=crop&h=800', 'Plumbing for shops, offices, restaurants, hospitals, hotels and housing societies.', '<p>Businesses and housing societies need plumbers who show up on schedule and work around operating hours. We handle repairs, upgrades and annual maintenance contracts for commercial premises and societies.</p>', '["Repairs across multiple floors","Restaurant kitchen drainage","Society tank and pump issues","Annual maintenance requirement"]', '["Site survey and scheduled visits","Repairs with minimal downtime","Society-level tank, pump and line work","Maintenance contracts"]', '[]', NULL, 0, 0, 1, 16, NULL, 'Plumbing for shops, offices, restaurants, hospitals, hotels and housing societies.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (18, 'plumbing-services', 'Plumbing Maintenance', 'plumbing-maintenance', 'clipboard', 'https://images.unsplash.com/photo-1620653713380-7a34b773fef8?w=1200&q=80&auto=format&fit=crop&h=800', 'Scheduled inspections and preventive maintenance for homes and societies.', '<p>A quarterly or half-yearly inspection catches small problems before they become emergencies. We check every line, tap, valve, tank and pump, fix minor issues on the spot and give you a written report.</p>', '["Recurring small leaks","Ageing pipes and fittings","Society-level upkeep","Peace of mind before monsoon"]', '["Full-house plumbing inspection","Tank cleaning and valve checks","Minor repairs on the spot","Written report with recommendations"]', '[]', NULL, 0, 0, 1, 17, NULL, 'Scheduled inspections and preventive maintenance for homes and societies.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
INSERT INTO `services` (`id`, `template`, `name`, `slug`, `icon`, `image`, `excerpt`, `description`, `problems`, `included`, `faqs`, `price_note`, `is_emergency`, `is_popular`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (19, 'plumbing-services', 'Sanitary Fitting Installation', 'sanitary-fitting-installation', 'wrench', 'https://images.unsplash.com/photo-1617850687405-a18454436d77?w=1200&q=80&auto=format&fit=crop&h=800', 'Installation of basins, WCs, showers, mixers, health faucets and accessories.', '<p>Bought new sanitaryware? We install basins, WCs, showers, mixers, health faucets and accessories with the right connectors and sealing, and test every joint before we leave.</p>', '["New basin, WC or shower","Replacing old fittings","Health faucet or jet spray","Bathroom accessories"]', '["Removal of old fittings","Installation with correct sealing","Angle valves and connectors","Leak test and clean-up"]', '[]', NULL, 0, 0, 1, 18, NULL, 'Installation of basins, WCs, showers, mixers, health faucets and accessories.', NULL, NULL, 0, '2026-09-21 09:48:59', '2026-09-21 09:48:59');
