lete the bathroom, in one order","text":"Mixers, showers, health faucets and accessories from Jaquar, Hindware & Cera.","cta_label":"Shop bathroom","url":"\\/shop\\/bathroom","image":"https:\\/\\/images.unsplash.com\\/photo-1652662700928-5a4685e87d64?w=900&q=80&auto=format&fit=crop&h=700","tone":"blue"},{"eyebrow":"Water pumps","heading":"Pumps that keep the pressure up","text":"Self-priming, submersible and openwell pumps from 0.5 HP to 2 HP.","cta_label":"Shop pumps","url":"\\/shop\\/water-pumps","image":"https:\\/\\/images.unsplash.com\\/photo-1534641614095-6222aed9bdd6?w=900&q=80&auto=format&fit=crop&h=700","tone":"orange"}],"bestsellers_heading":"Bestsellers","bestsellers_text":"What plumbers across India keep in the van.","bestsellers_limit":10,"brands_heading":"Trusted brands","brands_text":"Genuine stock, sourced directly from manufacturers and authorised distributors.","new_heading":"New arrivals","new_text":"Fresh additions to the catalogue.","new_limit":10,"why_heading":"Why buy from PlumbKart","why_items":[{"icon":"badge","title":"Genuine products","text":"Only authorised brands, with manufacturer warranty."},{"icon":"truck","title":"Fast delivery","text":"Dispatch within 24 hours, delivery across 18,000+ pincodes."},{"icon":"tag","title":"Competitive pricing","text":"Trade prices online, volume discounts for projects."},{"icon":"shield","title":"Secure payments","text":"UPI, cards, net banking, wallets and cash on delivery."},{"icon":"headset","title":"Expert support","text":"Talk to a plumbing expert on phone or WhatsApp."},{"icon":"rotate","title":"Easy returns","text":"7-day returns on unused products in original packing."}],"faq_heading":"Frequently asked questions"}', '2026-09-21 08:33:54', '2026-09-21 08:52:14');
INSERT INTO `settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('plumbing_services_site', '{"business_name":"PipeCare Plumbing Services","logo_primary":"Pipe","logo_accent":"Care","tagline":"Professional plumbers at your doorstep","phone":"+91 98765 43210","emergency_phone":"+91 98765 43210","whatsapp_number":"919876543210","whatsapp_message":"Hi PipeCare, I need help with a plumbing problem.","email":"help@pipecare.in","address":"SCO 88, 3rd Floor, Feroze Gandhi Market, Ludhiana, Punjab 141001","hours":"Mon\\u2013Sun, 8 am \\u2013 8 pm","emergency_available":true,"emergency_note":"24\\u00d77 emergency plumbing for burst pipes, major leaks and blocked drains.","response_note":"Plumber at your door in 60\\u201390 minutes in most areas","default_area":"Ludhiana","usp_strip":["Verified plumbers","Transparent pricing","Same-day service","30-day work warranty"],"search_placeholder":"Search plumbing services","search_suggestions":["leak repair","bathroom plumber","drain cleaning","tap repair","emergency plumber","water tank cleaning"],"stats":[{"value":"12+","label":"Years in service"},{"value":"25,000+","label":"Jobs completed"},{"value":"60","label":"Verified plumbers"},{"value":"4.8\\u2605","label":"Average rating"}],"social":[{"network":"facebook","url":"#"},{"network":"instagram","url":"#"},{"network":"youtube","url":"#"}],"footer_blurb":"PipeCare provides professional plumbing services for homes, shops and offices across Punjab \\u2014 leak repair, pipe work, drain cleaning, bathroom & kitchen plumbing, water tanks, pumps and 24\\u00d77 emergencies.","footer_note":"Background-verified plumbers \\u00b7 GST invoice on every job \\u00b7 Genuine ISI-marked parts","quote_heading":"Need a quote?","quote_text":"Tell us about your plumbing requirement \\u2014 a new bathroom, a full pipe replacement or regular maintenance \\u2014 and we will explain the work involved and the expected cost before anyone visits."}', '2026-09-21 09:48:57', '2026-09-21 09:48:57');
INSERT INTO `settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('plumbing_services_home', '{"sections":[{"key":"popular","enabled":true},{"key":"emergency","enabled":true},{"key":"problems","enabled":true},{"key":"how","enabled":true},{"key":"why","enabled":true},{"key":"areas","enabled":true},{"key":"reviews","enabled":true},{"key":"projects","enabled":true},{"key":"quote","enabled":true},{"key":"faq","enabled":true},{"key":"blog","enabled":true},{"key":"cta","enabled":true}],"hero_slides":[{"eyebrow":"Trusted local plumbers","title":"Plumbing problems? We fix them fast.","text":"Professional plumbing services at your doorstep \\u2014 leaks, pipes, drains, bathrooms, tanks and pumps.","image":"https:\\/\\/images.unsplash.com\\/photo-1676210134188-4c05dd172f89?w=1400&q=80&auto=format&fit=crop&h=900","cta_label":"Book a plumber","cta_url":"\\/book","secondary_label":"Call now","secondary_action":"call"},{"eyebrow":"24\\u00d77 emergency service","title":"Emergency plumbing, any hour.","text":"Burst pipe or major leak? Get professional help when you need it most.","image":"https:\\/\\/images.unsplash.com\\/photo-1526898943670-92bfa9f94c12?w=1400&q=80&auto=format&fit=crop&h=900","cta_label":"Get emergency help","cta_url":"\\/emergency","secondary_label":"Call now","secondary_action":"call"},{"eyebrow":"Same-day visits","title":"Need a plumber today?","text":"Fast response, transparent pricing and a warranty on every job.","image":"https:\\/\\/images.unsplash.com\\/photo-1542013936693-884638332954?w=1400&q=80&auto=format&fit=crop&h=900","cta_label":"Schedule a service","cta_url":"\\/book","secondary_label":"WhatsApp us","secondary_action":"whatsapp"}],"quick_actions":[{"label":"Emergency","icon":"alert","url":"\\/emergency","tone":"danger"},{"label":"Book plumber","icon":"calendar","url":"\\/book","tone":"primary"},{"label":"Get quote","icon":"file","url":"\\/quote","tone":"accent"},{"label":"WhatsApp","icon":"whatsapp","action":"whatsapp","tone":"whatsapp"}],"popular_heading":"Popular plumbing services","popular_sub":"The jobs we are called for most \\u2014 fixed by verified plumbers with a warranty.","popular_limit":8,"emergency_heading":"Plumbing emergency?","emergency_text":"Burst pipe? Major leakage? Blocked drain flooding the floor? Turn off the main valve and call us \\u2014 our emergency team responds round the clock.","emergency_points":["Response within 60 minutes","Available 24\\u00d77, including holidays","Temporary fix first, permanent repair next"],"problems_heading":"What\\u2019s the problem?","problems_sub":"Not sure what the service is called? Pick what\\u2019s wrong and we will take it from there.","problems":[{"label":"Water leakage","icon":"droplet","service":"leak-repair"},{"label":"Blocked drain","icon":"drain","service":"drain-cleaning"},{"label":"Low water pressure","icon":"gauge","service":"water-pressure-problems"},{"label":"Broken tap","icon":"tap","service":"tap-faucet-repair"},{"label":"Toilet problem","icon":"toilet","service":"toilet-repair"},{"label":"Pipe burst","icon":"alert","service":"emergency-plumbing"},{"label":"Bathroom leakage","icon":"bath","service":"bathroom-plumbing"},{"label":"No water supply","icon":"pump","service":"water-pump-services"},{"label":"Water tank problem","icon":"tank","service":"water-tank-services"},{"label":"Geyser not working","icon":"flame","service":"geyser-water-heater-plumbing"},{"label":"Kitchen sink issue","icon":"kitchen","service":"kitchen-plumbing"},{"label":"Something else","icon":"help","service":""}],"how_heading":"Getting a plumber is easy","how_steps":[{"title":"Tell us your problem","text":"Pick a service or describe what\\u2019s wrong \\u2014 online, on call or on WhatsApp.","icon":"chat"},{"title":"Choose a time","text":"Today, tomorrow or a date that suits you. Morning, afternoon or evening.","icon":"calendar"},{"title":"Our plumber visits","text":"A verified plumber arrives with the right tools and explains the fix and cost.","icon":"user-check"},{"title":"Problem gets fixed","text":"Work is completed, tested and covered by our 30-day warranty.","icon":"check-badge"}],"why_heading":"Why choose us?","why_items":[{"title":"Experienced plumbers","text":"Background-verified, trained professionals with years of hands-on experience.","icon":"badge"},{"title":"Fast response","text":"Same-day visits and a 60\\u201390 minute emergency response in most areas.","icon":"bolt"},{"title":"Transparent pricing","text":"You approve the estimate before work begins. No hidden charges.","icon":"rupee"},{"title":"Quality work","text":"Genuine ISI-marked parts and a 30-day warranty on every job.","icon":"shield"},{"title":"Reliable service","text":"On-time arrivals, clean work and a follow-up call after every visit.","icon":"clock"},{"title":"Local support","text":"A local team that knows your area, your water supply and your building.","icon":"map-pin"}],"areas_heading":"Plumbing services near you","areas_sub":"Local teams across Punjab and Chandigarh Tricity.","reviews_heading":"What our customers say","reviews_limit":8,"projects_heading":"Recent plumbing work","projects_sub":"Before and after \\u2014 real jobs by our team.","projects_limit":6,"faq_heading":"Frequently asked questions","faq_limit":8,"blog_heading":"Tips & guides","cta_heading":"Need a plumber?","cta_text":"Tell us what\\u2019s wrong. We\\u2019ll help you get it fixed \\u2014 today if possible.","cta_image":"https:\\/\\/images.unsplash.com\\/photo-1673870861507-d72aa6855d89?w=1200&q=80&auto=format&fit=crop&h=800"}', '2026-09-21 09:48:57', '2026-09-21 09:48:57');
